  static const List<String> frontGroups = ['traps', 'delts', 'chest', 'biceps', 'triceps', 'forearms', 'abs', 'quads', 'calves'];
  static const List<String> backGroups = ['traps', 'delts', 'lats', 'triceps', 'forearms', 'glutes', 'hamstrings', 'calves'];

  static List<AnatomyShape> shapesFor(bool front) => front ? frontShapes : backShapes;
  static Path silhouetteFor(bool front) => front ? frontSilhouette : backSilhouette;
  static List<String> groupsFor(bool front) => front ? frontGroups : backGroups;

  /// Группа мышц под точкой (в координатах базы) или null. Нейтральные сегменты «прозрачны» для нажатия:
  /// под портняжной выбирается квадрицепс.
  static String? groupAt(bool front, Offset p) {
    if (!silhouetteFor(front).contains(p)) return null;
    for (final s in shapesFor(front).reversed) {
      if (s.group != null && s.path.contains(p)) return s.group;
    }
    return null;
  }

  /// Разбор пути из генератора: только абсолютные M, C и Z.
  static Path _path(String d) {
    final p = Path();
    final t = RegExp(r'[MCZ]|-?[0-9.]+').allMatches(d).map((m) => m.group(0)!).toList();
    var i = 0;
    double n() => double.parse(t[i++]);
    while (i < t.length) {
      switch (t[i++]) {
        case 'M':
          p.moveTo(n(), n());
        case 'C':
          p.cubicTo(n(), n(), n(), n(), n(), n());
        case 'Z':
          p.close();
      }
    }
    return p;
  }
